    cl_پروگرام پروگرام_argsort_f32_i32;
    cl_پروگرام پروگرام_مجموع_صفیں_f32;
    cl_پروگرام پروگرام_pad;
    cl_پروگرام پروگرام_upscale;
    cl_پروگرام پروگرام_conv_2d_f16;
    cl_پروگرام پروگرام_conv_2d_f32;
    cl_پروگرام پروگرام_conv_2d_f16_f32;
    cl_پروگرام پروگرام_tsembd;
    cl_پروگرام پروگرام_gemv_moe_mxfp4_f32, پروگرام_gemm_moe_mxfp4_f32;
    cl_پروگرام پروگرام_mul_mv_id_q4_0_f32_8x_flat;
    cl_پروگرام پروگرام_mul_mv_id_q8_0_f32, پروگرام_mul_mv_id_q8_0_f32_flat;
