        CL_CHECK(cl_سیٹ_Kernel_Arg(kernel,  9, حجم(cl_ulong), &nb0));
        CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, 10, حجم(cl_ulong), &nb1));
