                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, k_arg++, حجم(صحیح),      &ne02));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, k_arg++, حجم(cl_ulong), &nb01));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, k_arg++, حجم(cl_ulong), &nb02));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, k_arg++, حجم(cl_ulong), &nb03));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, k_arg++, حجم(صحیح),      &ne10));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, k_arg++, حجم(صحیح),      &ne11));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, k_arg++, حجم(صحیح),      &ne12));
