                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_ulong),  &offsetd));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(صحیح),       &ne00));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(صحیح),       &ne01));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(صحیح),       &ne11));

