                    cl_image_format image_format_buf_dst = {CL_R, CL_FLOAT};
                    cl_image_desc image_desc_buf_dst = {CL_MEM_OBJECT_IMAGE1_D_بفر, static_cast<size_t>(ne0 * ne1 * ne2), 0,0,0,0,0,0,0, {sub_buf_dst}};
                    buf_dst_image = clCreateImage(backend_ctx->context, CL_MEM_WRITE_ONLY, &image_format_buf_dst, &image_desc_buf_dst, تہی, &حالت_2);
                    CL_CHECK(حالت_2);

                    // Set kernel args
                    صحیح arg_idx = 0;
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &extra0_q5_1->qs_img));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &extra0_q5_1->qh));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &extra0_q5_1->d));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &extra0_q5_1->m));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &image_src1_reordered));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &buf_src2));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &buf_src2_emap));
