            CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, 15, حجم(cl_ulong), &nb12));
            CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, 16, حجم(صحیح),      &ne20));
            CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, 17, حجم(صحیح),      &ne21));
            CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, 18, حجم(cl_ulong), &nb21));
            CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, 19, حجم(صحیح),      &ne0));
