                    cl_بفر_region region;
                    region.origin = offset2;
                    region.size = ne20 * ne21 * حجم(صحیح);
                    buf_src2 = cl_Create_Sub_بفر(extra2->ڈیٹا_device, 0, CL_بفر_CREATE_TYPE_REGION, &region, &حالت_2);
