                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &extra0_q4_K->d));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &extra0_q4_K->dm));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &extra0_q4_K->s));
