                    buf_src2 = cl_Create_Sub_بفر(backend_ctx->prealloc_post_رہنما_آلہ.بفر, 0, CL_بفر_CREATE_TYPE_REGION, &region, &حالت_2);
                    CL_CHECK(حالت_2);

                    region.origin = 0;
                    region.size = حجم(مختصر) * max_post_رہنما_آلہ_tile;
                    buf_src2_emap = cl_Create_Sub_بفر(backend_ctx->prealloc_emap.بفر, 0, CL_بفر_CREATE_TYPE_REGION, &region, &حالت_2);
                    CL_CHECK(حالت_2);

                    // Reorder activations
                    region.origin = offset1;
                    region.size = ne10 * ne11 * ne12 * حجم(اعشاری);
                    sub_buf_src1_pre = cl_Create_Sub_بفر(extra1->ڈیٹا_device, 0, CL_بفر_CREATE_TYPE_REGION, &region, &حالت_2);
                    CL_CHECK(حالت_2);

