                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &buf_src2_emap));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &buf_dst_image));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_mem),    &(backend_ctx->prealloc_کل_tiles.بفر)));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(صحیح),       &ne00));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(صحیح),       &ne01));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_uint),   &backend_ctx->adreno_use_moe_ragged));
                    CL_CHECK(cl_سیٹ_Kernel_Arg(kernel, arg_idx++, حجم(cl_uint),   &backend_ctx->adreno_moe_ragged_skip_gran));

                    // set thread grid
                    global_سائز[1] = static_cast<size_t>((ne01 + 63) / 64);
